import{_ as t,o as a,c as s,a6 as n}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Comprendre les classements et compétitions","description":"","frontmatter":{"title":"Comprendre les classements et compétitions","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"fr","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"dcf08e4ef08a28fc3e32216b2017b5f208afc57a91e537fd3b90a6f0ed1f041e","translationRevision":"84e2ef69f16a3be871639b862da514db1e1d22be5504770b81153cad74f0d880","order":30},"headers":[],"relativePath":"fr/user/points/rankings.md","filePath":"fr/user/points/rankings.md","lastUpdated":1794611623000}'),i={name:"fr/user/points/rankings.md"};function r(o,e,l,u,d,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="understand-rankings-and-competitions" tabindex="-1">Comprendre les classements et compétitions <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to &quot;Comprendre les classements et compétitions {#understand-rankings-and-competitions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Choisir la vue de classement appropriée et reconnaître les limites de l’espace de classements en développement. Une activité entrante est nécessaire pour obtenir des scores pertinents. Commencez par le classement ordinaire de <a href="./rules.html">Points</a> ou les panneaux des meilleurs spectateurs de <a href="./../live/feed.html">Live feed</a> pour simplement examiner les spectateurs actuels.</p><h2 id="use-the-right-view" tabindex="-1">Utiliser la bonne vue <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to &quot;Utiliser la bonne vue {#use-the-right-view}&quot;">​</a></h2><ol><li>Dans <strong>Points</strong>, recherchez un spectateur et triez par points, niveau ou identité. Actualisez avant de comparer un ajustement manuel à une attribution.</li><li>Dans <strong>Live feed</strong>, examinez les panneaux de classement de spectateurs disponibles. Ils peuvent recevoir des instantanés du moteur de classement indépendamment du tableau des soldes de points.</li><li>Pour une incrustation, ouvrez <a href="./../overlays/">Overlays</a>, sélectionnez le type de classement et examinez les options de source. Une source de classement configurée doit exister avant que sa sortie puisse apparaître.</li></ol><p>L’espace dédié <strong>Rankings &amp; competitions</strong> est expérimental. Sa route d’interface est <code>#/rankings</code>, mais il est volontairement masqué dans la navigation principale et n’est pas restauré comme onglet de démarrage. L’absence d’entrée latérale ne signifie pas que la route ou le moteur de classement a été supprimé.</p><h2 id="configure-an-experimental-ranking" tabindex="-1">Configurer un classement expérimental <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to &quot;Configurer un classement expérimental {#configure-an-experimental-ranking}&quot;">​</a></h2><p>Si votre environnement expose cet espace, commencez avec un créateur, une salle, un regroupement par utilisateur et une fenêtre de session. Ajoutez une métrique annoncée, telle que <code>tiktok.like</code> / <code>like.count</code>, avec un poids de <code>1</code>. Fixez une limite de résultats modeste et créez la définition. Le formulaire prend aussi en charge des fenêtres glissantes et quotidiennes, avec des bornes explicites de durée ou d’événements, ou un décalage de fuseau horaire.</p><p>Lisez l’instantané obtenu avant d’introduire d’autres sources. La pause et la reprise affectent la collecte du classement ; la réinitialisation efface intentionnellement son état. Les options de compétition et les sources liées aux votes ont leurs propres règles de regroupement. Ne supposez pas qu’une réinitialisation des points réinitialise aussi une compétition, ni que tous les regroupements personnalisés fonctionnent avec toutes les métriques.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les classements ordinaires sont disponibles ; la page de gestion dédiée reste expérimentale. Les scores proviennent de l’hôte et non du comptage des lignes affichées dans le flux. Ce guide ne démontre ni la validation en diffusion réelle/OBS ni celle de toutes les combinaisons de compétition.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Vérifiez le créateur, la salle, l’activation des sources, la fenêtre et l’état de pause lorsque les scores restent vides. Retirez les combinaisons source/regroupement non prises en charge plutôt que d’inventer des noms de champs. Préservez les données importantes par des <a href="./../preferences/backups.html">sauvegardes</a> avant toute réinitialisation, et incluez l’identifiant de définition et le code de diagnostic dans votre rapport.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>Le tableau Points demande 100 spectateurs et filtre/trie uniquement ces lignes. Actualiser ou trier par nom ne recherche pas toute la base. Les classements du fil affichent 10 lignes par session créateur/salle : diamants des cadeaux pour Top et quantités pour Likes, avec un suivi limité à 5 000 spectateurs. Ils ne mesurent pas les points enregistrés. Comparez d’abord unités et périodes.</p>',15)])])}const f=t(i,[["render",r]]);export{m as __pageData,f as default};
